cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void logsumexp_dim1_kernel(const float* __restrict__ inp,
                                      float* __restrict__ out,
                                      int N, int C, int D, int H, int W) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * D * H * W;
    if (index < total) {
        int w = index % W;
        int tmp = index / W;
        int h = tmp % H;
        tmp /= H;
        int d = tmp % D;
        int n = tmp / D;

        float maxv = -1e30f;
        for(int c=0; c < C; c++){
            float val = inp[(((n*C + c)*D + d)*H + h)*W + w];
            if(val > maxv) maxv = val;
        }
        float sumexp = 0.f;
        for(int c=0; c < C; c++){
            float val = inp[(((n*C + c)*D + d)*H + h)*W + w];
            sumexp += expf(val - maxv);
        }
        out[(((n*1 + 0)*D + d)*H + h)*W + w] = maxv + logf(sumexp);
    }
}

torch::Tensor logsumexp_dim1_cuda(torch::Tensor x) {
    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);
    auto out = torch::zeros({N, 1, D, H, W}, x.options());
    int total = N * D * H * W;
    int blockSize = 256;
    int numBlocks = (total + blockSize - 1) / blockSize;
    logsumexp_dim1_kernel<<<numBlocks, blockSize>>>(x.data_ptr<float>(),
                                                    out.data_ptr<float>(),
                                                    N, C, D, H, W);
    return out;
}

__global__ void hardswish_kernel(const float* __restrict__ inp,
                                 float* __restrict__ out,
                                 int size) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index < size) {
        float val = inp[index];
        float tmp = 1.f / (1.f + expf(-(val + 3.f)));
        out[index] = val * tmp / 6.f;
    }
}

torch::Tensor hardswish_cuda(torch::Tensor x) {
    auto out = torch::zeros_like(x);
    int size = x.numel();
    int blockSize = 256;
    int numBlocks = (size + blockSize - 1) / blockSize;
    hardswish_kernel<<<numBlocks, blockSize>>>(x.data_ptr<float>(),
                                               out.data_ptr<float>(),
                                               size);
    return out;
}

__global__ void sub_kernel(const float* __restrict__ x,
                           const float* __restrict__ y,
                           float* __restrict__ out,
                           int size) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index < size) {
        out[index] = x[index] - y[index];
    }
}

torch::Tensor sub_cuda(torch::Tensor x, torch::Tensor y) {
    auto y_expanded = y.expand_as(x);
    auto out = torch::zeros_like(x);
    int size = x.numel();
    int blockSize = 256;
    int numBlocks = (size + blockSize - 1) / blockSize;
    sub_kernel<<<numBlocks, blockSize>>>(x.data_ptr<float>(),
                                         y_expanded.data_ptr<float>(),
                                         out.data_ptr<float>(),
                                         size);
    return out;
}

__global__ void clamp_kernel(const float* __restrict__ inp,
                             float* __restrict__ out,
                             int size,
                             float min_val,
                             float max_val) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index < size) {
        float val = inp[index];
        val = (val < min_val) ? min_val : val;
        val = (val > max_val) ? max_val : val;
        out[index] = val;
    }
}

torch::Tensor clamp_cuda(torch::Tensor x, float min_val, float max_val) {
    auto out = torch::zeros_like(x);
    int size = x.numel();
    int blockSize = 256;
    int numBlocks = (size + blockSize - 1) / blockSize;
    clamp_kernel<<<numBlocks, blockSize>>>(x.data_ptr<float>(),
                                           out.data_ptr<float>(),
                                           size,
                                           min_val,
                                           max_val);
    return out;
}

__global__ void max_dim1_kernel(const float* __restrict__ inp,
                                float* __restrict__ out,
                                int N, int C, int D, int H, int W) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * D * H * W;
    if (index < total) {
        int w = index % W;
        int tmp = index / W;
        int h = tmp % H;
        tmp /= H;
        int d = tmp % D;
        int n = tmp / D;

        float maxv = -1e30f;
        for(int c=0; c < C; c++){
            float val = inp[(((n*C + c)*D + d)*H + h)*W + w];
            if(val > maxv) maxv = val;
        }
        out[(((n*1 + 0)*D + d)*H + h)*W + w] = maxv;
    }
