class ModelNew(nn.Module):
    """
    Model that performs a 3D transposed convolution, then replaces
    LogSumExp, HardSwish, subtraction, clamp, and maximum operations
    with custom CUDA kernels.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, bias_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels,
                                                 out_channels,
                                                 kernel_size,
                                                 stride=stride,
                                                 padding=padding)
        self.bias = nn.Parameter(torch.randn(bias_shape))

    def forward(self, x):
        x = self.conv_transpose(x)
        x = custom_ops.logsumexp_dim1_cuda(x)
        x = custom_ops.hardswish_cuda(x)
        x = custom_ops.sub_cuda(x, self.bias)
        x = custom_ops.clamp_cuda(x, -1.0, 1.0)
        x = custom_ops.max_dim1_cuda(x)
        return x

